import networkx as nx
from itertools import product, combinations

def get_perfect_matchings(G):
    nodes = sorted(list(G.nodes()))
    def backtrack(remaining_nodes):
        if not remaining_nodes:
            yield []
            return
        v = remaining_nodes[0]
        for neighbor in G.neighbors(v):
            if neighbor in remaining_nodes:
                # Remove v and neighbor
                new_remaining = [n for n in remaining_nodes if n != v and n != neighbor]
                for matching in backtrack(new_remaining):
                    yield [(v, neighbor)] + matching
    return list(backtrack(nodes))

def solve_for_n_optimized(n):
    G = nx.grid_2d_graph(n, n)
    all_matchings = get_perfect_matchings(G)

    cells = sorted(list(G.nodes()))

    # Try k = n, n+1, ...
    for k in range(1, n*n + 1):
        # We can iterate over subsets S, but that's too many.
        # Let's optimize.
        # Fix M* as the first matching in the list.
        # Because of symmetry, the smallest k should be the same.
        # Wait, that's only if we can pick any M*.
        # Let's try all possible M*? No, that's too many.
        # Let's try just one M* and see if we can find an S.

        # Let's try a few different M*s if needed.
        # For N=6, let's just try the most simple M* (horizontal)
        M_star = []
        for r in range(n):
            for c in range(0, n, 2):
                M_star.append(((r, c), (r, c + 1)))

        # S must contain at most one vertex from each edge in M_star.
        # This means for each edge (u, v) in M_star, we can pick u, v, or neither.
        # This is 3^(n^2/2) possibilities. Still too many.

        # Instead, let's try random S of size k and see if it works?
        # Or use a SAT solver / constraint solver.
        # But for n=6, k=6 is small. 
        # Let's try all combinations of size k.
        import itertools
        for S in itertools.combinations(cells, k):
            S_set = set(S)
            valid_matchings = 0
            for M in all_matchings:
                is_valid = True
                for edge in M:
                    if edge[0] in S_set and edge[1] in S_set:
                        is_valid = False
                        break
                if is_valid:
                    valid_matchings += 1
                if valid_matchings > 1:
                    break
            if valid_matchings == 1:
                return k
    return None

print(f"n=6: {solve_for_n_optimized(6)}")
